  bool _isToolContinuation(Context context) {
    for (final message in context.messages.reversed) {
      if (message is ToolResultMessage) return true;
      if (message is UserMessage) return false;
    }
    return false;
  }

  AssistantMessageEventStream call(
    Model model,
